    }
  },
  "signal_basis": {
    "component_id": "C009.signal_basis",
    "value": "Customer follow-ups produce documentation of reported offline preparation and intended roster timing, with retrospective reports and unknowns labeled and reported offline activity distinguished from logged events.",
    "scope": "Proposed supplementary documentation, assumed obtained for this assessment; no completed findings or verification of report truthfulness are implied.",
